# Databricks notebook source
# MAGIC %md
# MAGIC # Work types: last night's decisions, checked (oxjob #1976)
# MAGIC
# MAGIC The End 2 End cell (CreateWorksEnriched, generated by `lib/work_type_cell.py`) never fails End 2 End: on any error it keeps
# MAGIC the night before's decisions, and a decision that flips for no reason keeps last night's served type. This task, the first
# MAGIC of `Classify_Work_Types` after End 2 End, is where both fail loud (the job's failure email):
# MAGIC - **fell back**: `openalex_works` was published today but its type_decision wasn't decided today (`decided_on`);
# MAGIC - **unexplained flips** over `max_unexplained` (0): decisions that changed while their score, the policy, the model,
# MAGIC   the vocabulary, the list match and (for a fallback row) today's type all stayed the same.
# MAGIC It prints the night's report: decisions by outcome, flips by reason, served and held. Read-only.

# COMMAND ----------

import json

for name, default in [("schema", "openalex.works"), ("max_unexplained", "0")]:
    dbutils.widgets.text(name, default)  # noqa: F821
S = dbutils.widgets.get("schema").strip()  # noqa: F821
MAX_UNEXPLAINED = int(dbutils.widgets.get("max_unexplained"))  # noqa: F821
assert S.startswith("openalex.") and S.replace(".", "").replace("_", "").isalnum(), S
WORKS = f"{S}.openalex_works"

# COMMAND ----------

if "type_decision" not in {c.name for c in spark.table(WORKS).schema}:  # noqa: F821
    n_scores = spark.sql(f"SELECT count(*) AS n FROM {S}.work_type_scores").collect()[0].n  # noqa: F821
    if n_scores == 0:
        dbutils.notebook.exit("no scores yet and no type_decision: nothing to check")  # noqa: F821
    raise RuntimeError(f"{WORKS} has no type_decision although work_type_scores holds {n_scores:,} rows: the End 2 End cell "
                       "and its fallback both failed (CreateWorksEnriched's output)")
spark.sql(f"DESCRIBE HISTORY {WORKS} LIMIT 1").select("timestamp").createOrReplaceTempView("wt_pub")  # noqa: F821
p = spark.sql(f"""SELECT to_date((SELECT timestamp FROM wt_pub)) AS published,  -- noqa
    (SELECT count(*) FROM {S}.work_type_scores WHERE scored_at < (SELECT timestamp FROM wt_pub)) AS scored_before""").collect()[0]  # noqa: F821
published, scored_before = p.published, p.scored_before        # scores the last publish could have decided from
r = spark.sql(f"""SELECT count(*) AS decided, max(type_decision.decided_on) AS decided_on,  -- noqa
    count_if(type_decision.served) AS served, count_if(type_decision.held) AS held,
    count_if(type_decision.flip = 'unexplained') AS unexplained
  FROM {WORKS} WHERE type_decision IS NOT NULL""").collect()[0]  # noqa: F821
outcomes = {x[0]: x[1] for x in spark.sql(f"SELECT type_decision.outcome, count(*) FROM {WORKS} WHERE type_decision IS NOT NULL GROUP BY 1").collect()}  # noqa: F821
flips = {x[0]: x[1] for x in spark.sql(f"SELECT type_decision.flip, count(*) FROM {WORKS} WHERE type_decision.flip IS NOT NULL GROUP BY 1").collect()}  # noqa: F821
report = {"published": str(published), "scored_before": scored_before, "decided_on": str(r.decided_on), "decided": r.decided, "outcomes": outcomes,
          "flips": flips, "served": r.served, "held": r.held, "unexplained": r.unexplained}
print(json.dumps(report, indent=1, default=str))
bad = []
if scored_before and (not r.decided or r.decided_on is None or r.decided_on < published):
    bad.append(f"the cell fell back: {WORKS} was published {published} with {scored_before:,} scores loaded before it, but its "
               f"decisions are from {r.decided_on} ({r.decided:,} decided) (CreateWorksEnriched's work-type cell output says why)")
if r.unexplained > MAX_UNEXPLAINED:
    bad.append(f"{r.unexplained:,} unexplained flips (allowed {MAX_UNEXPLAINED}); {r.held:,} served works held on last night's type")
if bad:
    raise RuntimeError("; ".join(bad))
dbutils.notebook.exit(json.dumps(report, default=str))  # noqa: F821
